## TypeScript Example

```typescript
interface BlogPost {
  id: string;
  title: string;
  content: string;
  publishedAt: Date;
  tags: string[];
}

class BlogManager {
  private posts: BlogPost[] = [];

  addPost(post: Omit<BlogPost, 'id'>): BlogPost {
    const newPost: BlogPost = {
      ...post,
      id: crypto.randomUUID(),
    };

    this.posts.push(newPost);
    return newPost;
  }

  getPostsByTag(tag: string): BlogPost[] {
    return this.posts.filter(post => 
      post.tags.includes(tag)
    );
  }
}
```

Isn't the syntax highlighting beautiful? The code blocks are now properly styled with themes that adapt to light and dark modes!
